import AppKit
import Foundation
import PDFKit
import XCTest

/// Locates media generated by `Scripts/make_test_fixtures.sh` and builds the
/// fixtures that need Apple frameworks. Tests that need a missing fixture or
/// tool skip instead of failing, so CI without FFmpeg still runs the suite.
enum TestFixtures {
    static let generatedDirectory: URL = {
        URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent() // Support
            .deletingLastPathComponent() // FileConverterTests
            .deletingLastPathComponent() // Tests
            .appendingPathComponent("Fixtures/Generated", isDirectory: true)
    }()

    static func url(_ name: String) throws -> URL {
        let url = generatedDirectory.appendingPathComponent(name)
        guard FileManager.default.fileExists(atPath: url.path) else {
            throw XCTSkip("Fixture \(name) is missing. Run Scripts/make_test_fixtures.sh.")
        }
        return url
    }

    /// Copies a fixture into `directory` so a test can convert it without
    /// writing next to the shared fixture.
    static func copy(_ name: String, to directory: URL, as newName: String? = nil) throws -> URL {
        let source = try url(name)
        let destination = directory.appendingPathComponent(newName ?? source.lastPathComponent)
        try? FileManager.default.removeItem(at: destination)
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        try FileManager.default.copyItem(at: source, to: destination)
        return destination
    }

    static func requireTool(_ path: String) throws {
        guard FileManager.default.isExecutableFile(atPath: path) else {
            throw XCTSkip("\(path) is not installed.")
        }
    }

    static var ffmpegPath: String? {
        ["/opt/homebrew/bin/ffmpeg", "/usr/local/bin/ffmpeg"].first {
            FileManager.default.isExecutableFile(atPath: $0)
        }
    }

    static var ffprobePath: String? {
        ["/opt/homebrew/bin/ffprobe", "/usr/local/bin/ffprobe"].first {
            FileManager.default.isExecutableFile(atPath: $0)
        }
    }

    /// Three-page PDF whose crop box is smaller than its media box, with one
    /// link annotation and one outline entry.
    static func makeTextLinksOutlinePDF(in directory: URL) throws -> URL {
        let url = directory.appendingPathComponent("text_links_outline.pdf")
        let document = PDFDocument()
        for index in 0..<3 {
            let image = NSImage(size: NSSize(width: 612, height: 792), flipped: false) { rect in
                NSColor.white.setFill()
                rect.fill()
                return true
            }
            guard let page = PDFPage(image: image) else {
                throw XCTSkip("PDFKit could not create a page.")
            }
            page.setBounds(CGRect(x: 0, y: 0, width: 612, height: 792), for: .mediaBox)
            page.setBounds(CGRect(x: 36, y: 36, width: 540, height: 720), for: .cropBox)
            let text = PDFAnnotation(
                bounds: CGRect(x: 72, y: 600, width: 400, height: 40),
                forType: .freeText,
                withProperties: nil
            )
            text.contents = "Page \(index + 1) searchable text"
            text.font = NSFont.systemFont(ofSize: 18)
            page.addAnnotation(text)
            if index == 0 {
                let link = PDFAnnotation(
                    bounds: CGRect(x: 72, y: 500, width: 200, height: 20),
                    forType: .link,
                    withProperties: nil
                )
                link.url = URL(string: "https://example.com")
                page.addAnnotation(link)
            }
            document.insert(page, at: document.pageCount)
        }
        let outline = PDFOutline()
        let entry = PDFOutline()
        entry.label = "Chapter 1"
        if let first = document.page(at: 0) {
            entry.destination = PDFDestination(page: first, at: CGPoint(x: 0, y: 792))
        }
        outline.insertChild(entry, at: 0)
        document.outlineRoot = outline
        guard document.write(to: url) else {
            throw XCTSkip("PDFKit could not write the fixture PDF.")
        }
        return url
    }
}
